function recover(diskBalance, redoLsn, wal) {
  // wal: sorted array of { lsn, delta }, includes records before AND after the checkpoint
  let balance = diskBalance;
  for (const rec of wal) {
    if (rec.lsn >= redoLsn) {
      balance += rec.delta;
    }
  }
  return balance;
}

